import re, html
def sections():
    seen = set()
    for n in range(1, 73):
        try:
            kind, browse = fetch('https://asbar.org/legal-resources/code-annotated/?wpv_view_count=16436-TCPID13688&wpv_paged=' + str(n))
        except Exception as e:
            log('browse page failed ' + str(n) + ' ' + repr(e)); continue
        for url in dict.fromkeys(re.findall(r'href=["\'](https://asbar.org/code-annotated/[^?#"\']+/)', browse)):
            if url in seen:
                continue
            seen.add(url)
            try:
                kind, body = fetch(url)
            except Exception as e:
                log('section failed ' + url + ' ' + repr(e)); continue
            t = re.search(r'<title>\s*([0-9]+\.[0-9]+(?:\.[0-9]+)?)\s+(.*?)\s+-\s+American Samoa Bar Association', body, re.S)
            text = block_text(body, cls='fl-module-fl-post-content')          # the post body: the section and its history
            if t and text:
                yield {'id': t.group(1), 'heading': html.unescape(t.group(2)).strip(), 'text': text, 'url': url}
